import java.io.BufferedInputStream
import java.util.ArrayDeque
import kotlin.system.exitProcess
import kotlin.concurrent.thread

class Scan {
    private val buffer: ArrayDeque<String> = ArrayDeque()
    private val input = BufferedInputStream(System.`in`)
    private val sb = StringBuilder()

    private fun readLine(): String? {
        sb.setLength(0)
        var c: Int
        var readAny = false
        while (true) {
            c = input.read()
            if (c == -1) break
            readAny = true
            if (c == '\n'.code) break
            sb.append(c.toChar())
        }
        if (!readAny && sb.isEmpty()) return null
        return sb.toString()
    }

    fun <T> next(parse: (String) -> T): T {
        while (true) {
            val token = buffer.pollFirst()
            if (token != null) {
                return parse(token)
            }
            val line = readLine() ?: exitProcess(0)
            val parts = line.trim().split(Regex("\\s+"))
            buffer.clear()
            for (p in parts) {
                if (p.isNotEmpty()) buffer.addLast(p)
            }
        }
    }
}

fun _main() {
    val scan = Scan()
    var res = 0
    val n: Int = scan.next { it.toInt() }
    val m: Int = scan.next { it.toInt() }
    val limit = maxOf(n, m)
    for (i in 0..limit) {
        for (j in 0..limit) {
            if (i * i + j == n && i + j * j == m) {
                res += 1
            }
        }
    }
    println(res)
}

fun main() {
    val t = thread(start = true, isDaemon = false, name = "main-thread", stackSize = 1L shl 23) {
        _main()
    }
    t.join()
}

